using System;
using System.IO;
using System.Linq;
using System.Reflection;
using CircuitoStudio;
class CurvePersistenceTests {
 static int n;static void Check(bool b,string message){n++;if(!b)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(InvalidDataException){n++;return;}throw new Exception("Invalid stored curve accepted");}
 [STAThread] static void Main(){string directory=Path.Combine(Path.GetTempPath(),"curve-persistence-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{
  var project=Project.CreateSample();var board=project.Boards[0];var circuit=board.Circuits[0];var up=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;10;20\n100;1;2","montante-ensaio.csv");var down=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;1;2\n100;0.1;0.2","jusante-ensaio.csv");int changes=0;using(var form=new CurvesForm(project,board,circuit,delegate{changes++;})){form.CreateControl();form.ApplyCurve(true,up);Check(changes==1&&circuit.CurveStudy.Upstream!=null&&circuit.CurveStudy.Downstream==null,"Partial pair persists and notifies project immediately");up.Points[0].MinSeconds=999;Check(circuit.CurveStudy.Upstream.Points[0].MinSeconds==10,"Imported points copied independently");form.ApplyCurve(false,down);Check(changes==2&&CurveMath.Compare(circuit.CurveStudy.Upstream,circuit.CurveStudy.Downstream).Status.StartsWith("Envelopes separados"),"Completed stored pair retains comparison");var active=circuit.CurveStudy;Reject(delegate{form.ApplyCurve(true,new ManufacturerCurve{Source="inválida"});});Check(changes==2&&Object.ReferenceEquals(active,circuit.CurveStudy),"Invalid import does not replace stored pair or notify changes");}
  string file=Path.Combine(directory,"curves.circuito");project.Save(file);var loaded=Project.Load(file);var stored=loaded.Boards[0].Circuits[0].CurveStudy;Check(stored.Upstream.Source=="montante-ensaio.csv"&&stored.Downstream.Source=="jusante-ensaio.csv"&&stored.Upstream.Points.Count==2&&stored.Downstream.Points[1].MaxSeconds==.2,"Sources and all point values survive JSON");using(var form=new CurvesForm(loaded,loaded.Boards[0],loaded.Boards[0].Circuits[0])){form.CreateControl();var restored=(ManufacturerCurve)form.GetType().GetField("upstream",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(restored.Source==stored.Upstream.Source&&restored.Points[0].MinSeconds==10,"Reopened curve viewer restores saved envelopes");}
  var duplicate=ProjectEditing.DuplicateCircuit(project,board,circuit);Check(duplicate.CurveStudy!=null&&!Object.ReferenceEquals(duplicate.CurveStudy,circuit.CurveStudy)&&!Object.ReferenceEquals(duplicate.CurveStudy.Upstream.Points[0],circuit.CurveStudy.Upstream.Points[0]),"Circuit duplication deep copies curves and points");string memory=EngineeringReport.Memory(project,Engineering.Analyze(project));Check(memory.Contains("CURVAS ANEXADAS")&&memory.Contains("montante-ensaio.csv")&&memory.Contains("jusante-ensaio.csv"),"Memory includes attached curve references and comparison");byte[] before=File.ReadAllBytes(file);circuit.CurveStudy.Upstream.Points[0].CurrentA=Double.NaN;Reject(delegate{project.Save(file);});Check(File.ReadAllBytes(file).SequenceEqual(before),"Invalid stored curve cannot overwrite valid project");
  var empty=Project.CreateSample();empty.Save(Path.Combine(directory,"without-curves.circuito"));Check(Project.Load(Path.Combine(directory,"without-curves.circuito")).Boards[0].Circuits[0].CurveStudy==null,"Projects without optional curves remain supported");var maximum=new ManufacturerCurve{Source="Ensaio de limite de pontos"};for(int i=1;i<=100000;i++)maximum.Points.Add(new CurvePoint(i,1,2));empty.Boards[0].Circuits[0].CurveStudy=new CurveStudyData{Upstream=maximum};string maximumFile=Path.Combine(directory,"maximum.circuito");empty.Save(maximumFile);Check(Project.Load(maximumFile).Boards[0].Circuits[0].CurveStudy.Upstream.Points.Count==100000,"Supported maximum curve survives save/load");Console.WriteLine("PASS: "+n+" curve persistence assertions");
 }finally{Directory.Delete(directory,true);}}
}
